def title = reportType == 'AP' ? 'Accounts Payable Aging Report' : 'Accounts Receivable Aging Report' StringBuilder csv = new StringBuilder() csv.append('﻿') csv.append("${title}
") csv.append("As of: ${ec.l10n.format(new Date(), 'dd-MMM-yyyy')}

") csv.append("Party Name,Current,1-30 Days,31-60 Days,61-90 Days,91-120 Days,120+ Days,Total
")
for (def row : agingRows) { csv.append(""${row.partyName}",") csv.append("${ec.l10n.format(row.current, '#,##0.00')},") csv.append("${ec.l10n.format(row.days30, '#,##0.00')},") csv.append("${ec.l10n.format(row.days60, '#,##0.00')},") csv.append("${ec.l10n.format(row.days90, '#,##0.00')},") csv.append("${ec.l10n.format(row.days120, '#,##0.00')},") csv.append("${ec.l10n.format(row.days120plus, '#,##0.00')},") csv.append("${ec.l10n.format(row.total, '#,##0.00')}
") }
csv.append("
"TOTAL",") csv.append("${ec.l10n.format(totals.current, '#,##0.00')},") csv.append("${ec.l10n.format(totals.days30, '#,##0.00')},") csv.append("${ec.l10n.format(totals.days60, '#,##0.00')},") csv.append("${ec.l10n.format(totals.days90, '#,##0.00')},") csv.append("${ec.l10n.format(totals.days120, '#,##0.00')},") csv.append("${ec.l10n.format(totals.days120plus, '#,##0.00')},") csv.append("${ec.l10n.format(totals.total, '#,##0.00')}
")
ec.web.response.setContentType("text/csv; charset=utf-8") ec.web.response.setHeader("Content-Disposition", "attachment; filename="${reportType}_Aging_Report.csv"") ec.web.response.writer.write(csv.toString()) ec.web.response.writer.flush()

            def today = new java.util.Date()
            def partyMap = [:]

            for (def inv : openInvoices) {
                def partyId = isAR ? (inv.toPartyId ?: inv.fromPartyId) : (inv.fromPartyId ?: inv.toPartyId)
                def unpaid = ec.service.sync().name('zenith.sales.SalesLineServices.calculate#InvoiceDisplayAmounts').parameters([invoice:inv.getMap()]).call().outstandingAmount
                if (unpaid == 0) continue

                def invDate = inv.invoiceDate ?: inv.entryDate
                if (!invDate) continue
                def daysOverdue = ((today.time - invDate.time) / 86400000).intValue()

                if (!partyMap[partyId]) {
                    def partyDetail = ec.entity.find("mantle.party.PartyDetail").condition("partyId", partyId).one()
                    def pName = partyDetail?.organizationName ?: "${partyDetail?.firstName ?: ''} ${partyDetail?.lastName ?: ''}".trim() ?: partyId
                    partyMap[partyId] = [partyId: partyId, partyName: pName,
                        current: 0.0, days30: 0.0, days60: 0.0, days90: 0.0, days120: 0.0, days120plus: 0.0, total: 0.0]
                }

                def bucket = partyMap[partyId]
                bucket.total += unpaid
                if (daysOverdue <= 0) bucket.current += unpaid
                else if (daysOverdue <= 30) bucket.days30 += unpaid
                else if (daysOverdue <= 60) bucket.days60 += unpaid
                else if (daysOverdue <= 90) bucket.days90 += unpaid
                else if (daysOverdue <= 120) bucket.days120 += unpaid
                else bucket.days120plus += unpaid
            }

            agingRows = partyMap.values().toList().sort { a, b -> b.total <=> a.total }

            if (agingRows.isEmpty()) {
                showDemo = true
                if (isAR) {
                    agingRows = [
                        [partyName:'Reliance Retail Ltd.', current:180000, days30:95000, days60:45000, days90:0, days120:0, days120plus:0, total:320000],
                        [partyName:'Tata Consumer Products', current:120000, days30:80000, days60:0, days90:25000, days120:0, days120plus:0, total:225000],
                        [partyName:'DMart Ready', current:95000, days30:45000, days60:30000, days90:15000, days120:10000, days120plus:0, total:195000],
                        [partyName:'BigBasket (Supermarket)', current:75000, days30:50000, days60:25000, days90:0, days120:0, days120plus:12000, total:162000],
                        [partyName:'Spencer Retail', current:60000, days30:35000, days60:0, days90:0, days120:0, days120plus:0, total:95000],
                        [partyName:'Metro Cash & Carry', current:45000, days30:0, days60:20000, days90:10000, days120:5000, days120plus:8000, total:88000]
                    ]
                } else {
                    agingRows = [
                        [partyName:'ABC Wholesale Supplies', current:250000, days30:120000, days60:50000, days90:0, days120:0, days120plus:0, total:420000],
                        [partyName:'PQR Packaging Ltd.', current:85000, days30:65000, days60:30000, days90:20000, days120:0, days120plus:0, total:200000],
                        [partyName:'Fresh Farm Produce', current:120000, days30:45000, days60:0, days90:0, days120:0, days120plus:0, total:165000],
                        [partyName:'National Distributors', current:60000, days30:40000, days60:25000, days90:15000, days120:10000, days120plus:5000, total:155000],
                        [partyName:'City Logistics Corp.', current:45000, days30:30000, days60:0, days90:0, days120:0, days120plus:0, total:75000]
                    ]
                }
            }

            totals = [current:0, days30:0, days60:0, days90:0, days120:0, days120plus:0, total:0]
            for (def r : agingRows) {
                totals.current += r.current
                totals.days30 += r.days30
                totals.days60 += r.days60
                totals.days90 += r.days90
                totals.days120 += r.days120
                totals.days120plus += r.days120plus
                totals.total += r.total
            }

            overdueTotal = totals.days30 + totals.days60 + totals.days90 + totals.days120 + totals.days120plus
            overduePercent = totals.total > 0 ? ((overdueTotal / totals.total) * 100).intValue() : 0
